package org.x402.mechanisms.cardano;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.x402.mechanisms.cardano.utils.Jcs;

/**
 * {@link Jcs#number} against ECMAScript {@code Number#toString}: every power of two from 2^-1074
 * to 2^1023, compared with a vector generated by node ({@code String(2**k)}).
 */
class JcsPowersOfTwoTest {

  @Test
  void everyPowerOfTwoMatchesV8() throws IOException {
    List<String> expected;
    try (InputStream in = JcsPowersOfTwoTest.class.getResourceAsStream("/jcs/powers-of-two.txt")) {
      expected = new String(in.readAllBytes(), StandardCharsets.UTF_8).lines().toList();
    }
    assertThat(expected).hasSize(2098);
    for (int i = 0; i < expected.size(); i++) {
      int k = -1074 + i;
      assertThat(Jcs.number(Math.scalb(1.0, k))).as("2^%d", k).isEqualTo(expected.get(i));
    }
  }
}
